import{_ as t,c as e,a2 as r,o}from"./chunks/framework.Dz7_3PEu.js";const l="/assets/%E6%99%BA%E8%83%BD%E5%90%88%E7%BA%A6%E5%85%A8%E7%94%9F%E5%91%BD%E5%91%A8%E6%9C%9F%E7%AE%A1%E7%90%86.kSMP6u4U.png",i="/assets/%E5%90%88%E7%BA%A6%E7%8A%B6%E6%80%81%E6%B5%81%E7%A8%8B%E5%9B%BE.IJgS28Xj.png",q=JSON.parse('{"title":"合约生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"source/contract/contractLifecycle.md","filePath":"source/contract/contractLifecycle.md","lastUpdated":1736756758000}'),d={name:"source/contract/contractLifecycle.md"};function h(c,a,n,s,u,p){return o(),e("div",null,a[0]||(a[0]=[r('<h1 id="合约生命周期" tabindex="-1">合约生命周期 <a class="header-anchor" href="#合约生命周期" aria-label="Permalink to &quot;合约生命周期&quot;">​</a></h1><h2 id="设计和实现方案" tabindex="-1">设计和实现方案 <a class="header-anchor" href="#设计和实现方案" aria-label="Permalink to &quot;设计和实现方案&quot;">​</a></h2><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>当前所有节点都可以部署合约，从而执行一个合约。</p><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>智能合约的部署、升级、冻结、解冻、吊销都需要受控。</p><p>合约部署之后需要经过投票生效后才能调用，同样升级、冻结、解冻，吊销等均需要进行投票后才会生效。</p><p>投票规则：达到2/3见证节点同意或者1/3见证节点反对，投票立即结束（尚未进行投票的见证节点无需投票），合约状态发生流转。</p><blockquote><p>2/3 这个比例要参考具体的共识。</p></blockquote><h2 id="总体设计" tabindex="-1">总体设计 <a class="header-anchor" href="#总体设计" aria-label="Permalink to &quot;总体设计&quot;">​</a></h2><h3 id="生命周期流程图" tabindex="-1">生命周期流程图 <a class="header-anchor" href="#生命周期流程图" aria-label="Permalink to &quot;生命周期流程图&quot;">​</a></h3><p><img src="'+l+'" alt="智能合约全生命周期管理"></p><h3 id="解释说明" tabindex="-1">解释说明 <a class="header-anchor" href="#解释说明" aria-label="Permalink to &quot;解释说明&quot;">​</a></h3><ul><li>合约部署之后，会自动发起部署投票。2/3见证节点同意后，合约变更为生效状态，所有账户均可对该合约进行调用。</li><li>生效状态下的合约可进行升级、冻结、吊销投票。</li><li>解冻投票仅能在合约冻结状态下发起。</li><li>仅在投票通过情况下，才能发生合约状态变化。</li><li>除了部署之外，升级、吊销、冻结、解冻均可多次发起投票（合约的上一轮投票需要结束）。</li></ul><h2 id="模块设计" tabindex="-1">模块设计 <a class="header-anchor" href="#模块设计" aria-label="Permalink to &quot;模块设计&quot;">​</a></h2><h3 id="状态设计" tabindex="-1">状态设计 <a class="header-anchor" href="#状态设计" aria-label="Permalink to &quot;状态设计&quot;">​</a></h3><p>合约分为未生效状态（吊销状态属于未生效状态），生效状态，冻结状态。</p><p>未生效状态合约不可调用，生效状态可正常调用，冻结状态合约不可调用。</p><h3 id="状态流转" tabindex="-1">状态流转 <a class="header-anchor" href="#状态流转" aria-label="Permalink to &quot;状态流转&quot;">​</a></h3><h3 id="合约状态" tabindex="-1">合约状态 <a class="header-anchor" href="#合约状态" aria-label="Permalink to &quot;合约状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td>0</td><td>禁止执行</td><td></td></tr><tr><td>1</td><td>允许执行</td><td></td></tr><tr><td>2</td><td>冻结状态</td><td></td></tr></tbody></table><h4 id="查询" tabindex="-1">查询 <a class="header-anchor" href="#查询" aria-label="Permalink to &quot;查询&quot;">​</a></h4><p>latc_getContractState</p><h3 id="合约状态流转图" tabindex="-1">合约状态流转图 <a class="header-anchor" href="#合约状态流转图" aria-label="Permalink to &quot;合约状态流转图&quot;">​</a></h3><p><img src="'+i+'" alt="合约状态流程图"></p>',25)]))}const m=t(d,[["render",h]]);export{q as __pageData,m as default};
